namespace Bazaar.CompanyIdentity;

/// <summary>
/// Writes a company build's server identity as source (doc 37 section 4a). The generated file replaces the unset placeholder
/// <c>CompanyBuildIdentity.cs</c> in the client build's copy of Bazaar.Client.Core, so each build is bound to its server.
/// Generation is pure text: nothing is compiled or executed here.
/// </summary>
public static class CompanyBuildIdentityGenerator
{
    /// <summary>Renders the complete C# source for the identity.</summary>
    public static string RenderSource(CompanyServerIdentity identity)
    {
        ArgumentNullException.ThrowIfNull(identity);
        var address = EscapeLiteral(identity.Address.AbsoluteUri);
        var pin = EscapeLiteral(identity.KeyHashPin);
        return $$"""
            // <auto-generated>
            // Generated by the company server for this build (doc 37 section 4a). Do not edit.
            // </auto-generated>
            namespace Bazaar.CompanyIdentity;

            /// <summary>The company server this client build was made for. Generated; the unset placeholder is replaced by it.</summary>
            public static class CompanyBuildIdentity
            {
                /// <summary>The server's base address.</summary>
                public static Uri? Address => new Uri("{{address}}");

                /// <summary>The SHA-256 pin of the server's key.</summary>
                public static string? KeyHashPin => "{{pin}}";
            }

            """;
    }

    /// <summary>Writes the generated source to <c>CompanyBuildIdentity.cs</c> in <paramref name="projectDirectory"/>, replacing the placeholder.</summary>
    /// <returns>The full path written.</returns>
    public static string WriteSource(CompanyServerIdentity identity, string projectDirectory)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(projectDirectory);
        var path = Path.Combine(projectDirectory, "CompanyBuildIdentity.cs");
        var directory = Path.GetDirectoryName(path)!;
        Directory.CreateDirectory(directory);
        File.WriteAllText(path, RenderSource(identity), new System.Text.UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
        return path;
    }

    private static string EscapeLiteral(string value) =>
        value.Replace("\\", "\\\\", StringComparison.Ordinal).Replace("\"", "\\\"", StringComparison.Ordinal);
}
